from typing import Callable, Dict, List, Optional

class BackgroundJob:
    def __init__(self, queue: List[Dict[str, str]], max_retries: int = 3, max_delay: float = 60):
        self.queue = queue
        self.max_retries = max_retries
        self.max_delay = max_delay
        self.current_retries = 0
        self.current_delay = 0

    def enqueue(self, job: Dict[str, str]):
        self.queue.append(job)

    def process(self) -> Optional[Dict[str, str]]:
        while True:
            if not self.queue:
                return None
            job = self.queue.pop(0)
            if job["type"] == "deadline":
                return job
            elif job["type"] == "retry":
                self.current_retries += 1
                if self.current_retries > self.max_retries:
                    return None
                if time.time() - self.current_delay < 1:
                    return job
                self.current_delay = time.time() + 1
            elif job["type"] == "timeout":
                return None
            elif job["type"] == "poison":
                return None
            elif job["type"] == "worker-crash":
                return None
            else:
                raise ValueError(f"Unknown job type: {job['type']}")
            time.sleep(0.1)

    def is_valid(self) -> bool:
        return self.current_retries < self.max_retries and self.current_delay < self.max_delay

class BackgroundJobQueue:
    def __init__(self, max_retries: int = 3, max_delay: float = 60):
        self.background_jobs = []
        self.max_retries = max_retries
        self.max_delay = max_delay

    def enqueue(self, job: Dict[str, str]):
        self.background_jobs.append(BackgroundJob(self.background_jobs, max_retries, max_delay))

    def process(self) -> Optional[Dict[str, str]]:
        while self.background_jobs:
            job = self.background_jobs.pop(0).process()
            if job is None:
                return None
            if job["type"] == "deadline":
                return job
            elif job["type"] == "retry":
                self.background_jobs.append(BackgroundJob(self.background_jobs, max_retries, max_delay))
            elif job["type"] == "timeout":
                return None
            elif job["type"] == "poison":
                return None
            elif job["type"] == "worker-crash":
                return None
            else:
                raise ValueError(f"Unknown job type: {job['type']}")
        return None
