class ReadThroughCache:
    def __init__(self, max_size: int, eviction_policy: str = "least_recent"):
        self.max_size = max_size
        self eviction_policy = eviction_policy
        self.cache = {}
        self.last_validated = {}

    def put(self, key: str, value: any):
        if key in self.cache:
            self._validate_key(key)
        if len(self.cache) >= self.max_size:
            self._evict_largest()
        self.cache[key] = value
        self.last_validated[key] = datetime.now()

    def get(self, key: str) -> any:
        if key not in self.cache:
            self._validate_key(key)
        if key in self.last_validated:
            return self.last_validated[key]
        return None

    def _validate_key(self, key: str) -> None:
        if self eviction_policy == "least_recent":
            if key in self.cache and self.last_validated[key] < datetime.now() - 1:
                del self.cache[key]
        elif self eviction_policy == "stale-while-revalidate":
            if key in self.cache and self.last_validated[key] < datetime.now():
                self._validate_key(key)
        else:
            raise ValueError("Invalid eviction policy")

    def _evict_largest(self) -> None:
        keys = sorted(self.cache.keys())
        for key in keys[:-1]:
            del self.cache[key]
        del self.cache[keys[-1]]
        self.last_validated[keys[-1]] = datetime.now()
