        if event_id in self.replay:
            event = next((e for e in self.replay[event_id] if e.timestamp <= self.version), None)
            if event:
                self.events.append(event)
                self.replay[event_id] = event

    def snapshot(self, event_id: str, max_version: int = 100):
        if event_id not in self.replay:
            return None
        return self.replay[event_id]

    def replay(self, event_id: str, max_version: int = 100):
        if event_id not in self.replay:
            return None
        return self.replay[event_id]

    def validate(self, event: Event):
        if event.version > self.version:
            return False
        return True

    def validate_snapshot(self, event_id: str, max_version: int = 100):
        return self.validate(self.snapshot(event_id, max_version))

    def validate_replay(self, event_id: str, max_version: int = 100):
        return self.validate(self.replay(event_id, max_version))

    def create(self, event: Event):
        self.commit(event)
        return event

    def get(self, event_id: str):
        return self.replay.get(event_id)

    def get_latest(self, event_id: str):
        return self.replay.get(event_id, None)

