from typing import Dict, List

class Record:
    def __init__(self, id: int, timestamp: int, value: int):
        self.id = id
        self.timestamp = timestamp
        self.value = value

class Deduplication:
    def __init__(self):
        self.records: Dict[int, Record] = {}

    def add(self, record: Record):
        self.records[record.id] = record

    def get(self, id: int) -> Record:
        return self.records.get(id, None)

    def remove(self, id: int):
        if id in self.records:
            del self.records[id]

    def checkpoint(self):
        for id, record in self.records.items():
            if record.timestamp > time.time():
                self.remove(id)

    def validate(self):
        for id, record in self.records.items():
            if record.timestamp > time.time():
                return False
        return True

class Pipeline:
    def __init__(self, deduplication: Deduplication, checkpointer: callable):
        self.deduplication = deduplication
        self.checkpointer = checkpointer()

    def run(self, records: List[Record]):
        for record in records:
            if not self.deduplication.validate():
                continue
            self.deduplication.add(record)
            self.checkpointer.checkpoint()
            if record.timestamp > time.time():
                self.deduplication.remove(record.id)

def import_records(records: List[Record], deduplication: Deduplication, checkpointer: callable):
    pipeline = Pipeline(deduplication, checkpointer)
    for record in records:
        pipeline.run([record])
    return pipeline.deduplication.records

