import threading
from typing import Dict, List, Optional

class DatabaseMigration:
    def __init__(self, new_column: str, old_column: str, max_backfill_size: int = 1000):
        self.new_column = new_column
        self.old_column = old_column
        self.max_backfill_size = max_backfill_size
        self.backfill_queue: List[Dict[str, str]] = []
        self.lock = threading.Lock()

    def add_backfill(self, version: int, data: Dict[str, str]):
        with self.lock:
            if len(self.backfill_queue) >= self.max_backfill_size:
                raise ValueError("Backfill queue is full")
            self.backfill_queue.append(data)

    def verify(self, version: int):
        with self.lock:
            if len(self.backfill_queue) > version:
                raise ValueError("Backfill queue is out of order")
            return self.backfill_queue[version]

    def backfill(self, version: int):
        with self.lock:
            data = self.verify(version)
            if data:
                self.add_backfill(version, data)
            else:
                raise ValueError("No data to backfill")

    def rollback(self, version: int):
        with self.lock:
            if version < 1:
                raise ValueError("Invalid version")
            for data in self.backfill_queue[:version]:
                self.add_backfill(version, data)
            self.backfill_queue = []

    def get_version(self) -> Optional[int]:
        with self.lock:
            return self.backfill_queue[-1].get("version", None)

def create_database_migration(new_column: str, old_column: str, max_backfill_size: int = 1000):
    return DatabaseMigration(new_column, old_column, max_backfill_size)
